// Helper to switch to mock mode
export function enableMockMode() {
  if (!useMock) {
    useMock = true;
    localStorage.setItem(USE_MOCK_SUPABASE_KEY, 'true');
    window.dispatchEvent(new Event('supabase_mock_mode_enabled'));
  }
}

// Check if mock mode is active
