function createMockUser(email: string, fullName: string) {
  const id = 'mock-user-id-' + Math.random().toString(36).substring(2, 11);
  const user = {
    id,
    aud: 'authenticated',
    role: 'authenticated',
    email,
    email_confirmed_at: new Date().toISOString(),
    phone: '',
    confirmed_at: new Date().toISOString(),
    last_sign_in_at: new Date().toISOString(),
    app_metadata: { provider: 'email', providers: ['email'] },
    user_metadata: { full_name: fullName },
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };

  const users = getMockUsers();
  users.push(user);
  saveMockUsers(users);

  // Add profile
  const profiles = getMockProfiles();
  profiles.push({
    id,
    email,
    full_name: fullName,
    avatar_url: `https://api.dicebear.com/7.x/adventurer/svg?seed=${encodeURIComponent(fullName)}`,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  });
  saveMockProfiles(profiles);

  // Add user role
  const roles = getMockRoles();
  // If first user, make them admin
  const role = roles.length === 0 ? 'admin' : 'recruiter';
  roles.push({
    id: 'mock-role-id-' + Math.random().toString(36).substring(2, 11),
    user_id: id,
    role,
    created_at: new Date().toISOString()
  });
  saveMockRoles(roles);

  return user;
}

let mockAuthListeners: any[] = [];
function triggerAuthChange(event: string, session: any) {
  mockAuthListeners.forEach(listener => {
    try {
      listener(event, session);
    } catch (e) {
      console.error('Error in auth state change listener:', e);
    }
  });
}

